def nests(outcomps):
    # A comp A is a strict sub-compartment of B if bbox(A) strictly inside bbox(B) and interiors overlap appropriately
    # Use: bbox A contained in bbox B and bbox area difference > 0
    H=[]
    for a in outcomps:
        H.append(a)
    S=defaultdict(list)
    for i,A in enumerate(H):
        for j,B in enumerate(H):
            if A['bbox']!=B['bbox']:
                ra,rb,ca,cb=A['bbox']; RJB=B['bbox']
                if rb-ra>=1 and cb-ca>=1:
                    pass
                # candidate parent: A entirely within B's bbox
                if ca>=RJB[0] and cb<=RJB[2] and ra>=RJB[0] and rb<=RJB[1]:
                    S[B].append(i)
    return S,S
